albums = FileAttachment("data/albums.csv").csv()

artists = [...new Set(albums.map(d =&gt; d.artist))]

viewof selectedArtist = Inputs.select(artists, {
  label: "Select an artist:"
})

artistImages = ({
  "Ariana Grande": "data/artists/ariana_grande.jpg",
  "Bad Bunny": "data/artists/bad_bunny.jpg",
  "Billie Eilish": "data/artists/billie_eilish.jpg",
  "Bruce Springsteen": "data/artists/bruce_springsteen.jpg",
  "Chappell Roan": "data/artists/chappell_roan.jpg",
  "Doja Cat": "data/artists/doja_cat.jpg",
  "Drake": "data/artists/drake.jpg",
  "Dua Lipa": "data/artists/dua_lipa.jpg",
  "Harry Styles": "data/artists/harry_styles.jpg",
  "Kendrick Lamar": "data/artists/kendrick_lamar.jpg",
  "Kodak Black": "data/artists/kodak_black.png",
  "Olivia Rodrigo": "data/artists/olivia_rodrigo.jpg",
  "Post Malone": "data/artists/post_malone.jpg",
  "Sabrina Carpenter": "data/artists/sabrina_carpenter.jpg",
  "SZA": "data/artists/sza.jpg",
  "Taylor Swift": "data/artists/taylor_swift.png",
  "The Weeknd": "data/artists/the_weeknd.jpg",
  "Travis Scott": "data/artists/travis_scott.jpg",
  "Tyler, The Creator": "data/artists/tyler_the_creator.jpg"
})

html`
&lt;div id="artist-backdrop"&gt;
  &lt;div class="backdrop-photo" style="background-image: url('${artistImages[selectedArtist] || ""}');"&gt;&lt;/div&gt;
  &lt;div class="backdrop-gradient"&gt;&lt;/div&gt;
&lt;/div&gt;
`



































filteredAlbums = albums.filter(d =&gt; d.artist === selectedArtist)

viewof selected = Inputs.select(filteredAlbums, {
  label: "Select an album:",
  format: d =&gt; d.title
})

fetchPreview = async (artist, song, existingUrl) =&gt; {
  if (existingUrl && existingUrl !== "NA" && existingUrl !== "") return existingUrl;
  if (!song || !artist) return null;
  try {
    const clean = song.replace(/\s*\(.*?\)/g, "").trim();
    const query = encodeURIComponent(`${artist} ${clean}`);
    const res = await fetch(`https://itunes.apple.com/search?term=${query}&entity=song&limit=1`);
    if (!res.ok) return null;
    const data = await res.json();
    return data.results?.[0]?.previewUrl || null;
  } catch (e) {
    return null;
  }
}

preview1 = selected && selected.top_song_1 ? fetchPreview(selected.artist, selected.top_song_1, selected.top_song_1_preview) : null
preview2 = selected && selected.top_song_2 ? fetchPreview(selected.artist, selected.top_song_2, selected.top_song_2_preview) : null
preview3 = selected && selected.top_song_3 ? fetchPreview(selected.artist, selected.top_song_3, selected.top_song_3_preview) : null












































html`
&lt;div class="album-card"&gt;
  ${selected ? html`
    &lt;h3&gt;${selected.title}&lt;/h3&gt;
    &lt;p&gt;&lt;strong&gt;Artist:&lt;/strong&gt; ${selected.artist}&lt;/p&gt;
    &lt;p&gt;&lt;strong&gt;Release Date:&lt;/strong&gt; ${selected.release_date}&lt;/p&gt;
    ${selected.streams ? html`&lt;p&gt;&lt;strong&gt;Total Spotify Streams:&lt;/strong&gt; ${Number(selected.streams).toLocaleString()}&lt;/p&gt;` : ""}
    ${selected.youtube_views ? html`&lt;p&gt;&lt;strong&gt;Total YouTube Views:&lt;/strong&gt; ${Number(selected.youtube_views).toLocaleString()}&lt;/p&gt;` : ""}
    ${selected.cover_path ? html`&lt;img src="${selected.cover_path}" alt="${selected.title}" style="max-width: 350px; border-radius: 8px; box-shadow: 0 4px 6px rgba(0,0,0,0.1);"&gt;` : ""}

    ${selected.top_song_1 ? html`
      &lt;h4 style="margin-top: 1em;"&gt;Top 3 Most Streamed Songs&lt;/h4&gt;
      &lt;ol style="padding-left: 1.2em;"&gt;
        &lt;li style="margin-bottom: 0.8em;"&gt;
          &lt;div&gt;&lt;strong&gt;${selected.top_song_1}&lt;/strong&gt;&lt;/div&gt;
          ${preview1 ? html`&lt;audio controls style="margin-top: 4px; height: 32px; width: 100%; max-width: 320px;" src="${preview1}"&gt;&lt;/audio&gt;` : ""}
        &lt;/li&gt;
        ${selected.top_song_2 ? html`
        &lt;li style="margin-bottom: 0.8em;"&gt;
          &lt;div&gt;&lt;strong&gt;${selected.top_song_2}&lt;/strong&gt;&lt;/div&gt;
          ${preview2 ? html`&lt;audio controls style="margin-top: 4px; height: 32px; width: 100%; max-width: 320px;" src="${preview2}"&gt;&lt;/audio&gt;` : ""}
        &lt;/li&gt;` : ""}
        ${selected.top_song_3 ? html`
        &lt;li style="margin-bottom: 0.8em;"&gt;
          &lt;div&gt;&lt;strong&gt;${selected.top_song_3}&lt;/strong&gt;&lt;/div&gt;
          ${preview3 ? html`&lt;audio controls style="margin-top: 4px; height: 32px; width: 100%; max-width: 320px;" src="${preview3}"&gt;&lt;/audio&gt;` : ""}
        &lt;/li&gt;` : ""}
      &lt;/ol&gt;
    ` : ""}
  ` : ""}
&lt;/div&gt;
`
